when.condition:
@{
                var body = (JObject)context.Variables["code-interpreter-request"];
                var store = body["store"];
                var tools = body["tools"] as JArray;
                var tool = tools != null && tools.Count == 1
                  ? tools[0] as JObject
                  : null;
                var container = tool?["container"] as JObject;
                var fileIds = container?["file_ids"];
                var background = body["background"];
                var allowedFields = new [] {
                  "model",
                  "tools",
                  "instructions",
                  "input",
                  "store",
                  "background",
                  "previous_response_id"
                };
                return !"{{code-interpreter-model}}".Equals(
                    (string)body["model"],
                    StringComparison.Ordinal
                  )
                  || body.Properties().Any(p => !allowedFields.Contains(p.Name))
                  || store == null
                  || store.Type != JTokenType.Boolean
                  || store.Value<bool>()
                  || body["instructions"]?.Type != JTokenType.String
                  || ((string)body["instructions"]).Length > 60000
                  || body["input"]?.Type != JTokenType.String
                  || ((string)body["input"]).Length > 60000
                  || tool == null
                  || !"code_interpreter".Equals(
                    (string)tool["type"],
                    StringComparison.Ordinal
                  )
                  || tool.Properties().Any(
                    p => p.Name != "type" && p.Name != "container"
                  )
                  || container == null
                  || !"auto".Equals(
                    (string)container["type"],
                    StringComparison.Ordinal
                  )
                  || container.Properties().Any(
                    p => p.Name != "type" && p.Name != "file_ids"
                  )
                  || (fileIds != null && (
                    fileIds.Type != JTokenType.Array
                    || ((JArray)fileIds).Count > 8
                    || ((JArray)fileIds).Any(id =>
                      id.Type != JTokenType.String
                      || ((string)id).Length > 128
                      || !((string)id).StartsWith("file-", StringComparison.Ordinal)
                    )
                  ))
                  || body["previous_response_id"] != null
                  || (background != null && (
                    background.Type != JTokenType.Boolean
                    || background.Value<bool>()
                  ));
              }

@{
                var contentType = context.Request.Headers.GetValueOrDefault("Content-Type", "");
                var upload = (byte[])context.Variables["code-interpreter-upload"];
                var multipart = System.Text.Encoding.UTF8.GetString(upload);
                return !contentType.StartsWith("multipart/form-data;", StringComparison.OrdinalIgnoreCase)
                  || upload.Length > 26300000
                  || !multipart.Contains(
                    "name=\"purpose\"\r\n\r\nassistants"
                  );
              }

set-variable.value:
@{
      var supplied = context.Request.Headers.GetValueOrDefault("x-correlation-id", "");
      return !String.IsNullOrWhiteSpace(supplied) && supplied.Length <= 128
        ? supplied
        : context.RequestId.ToString();
    }
